            7: (0, 0, 0, 1),
            8: (3, 0, 0, 0),
            9: (0, 2, 0, 0),
        }

        def count(N: int) -> int:
            if N < 1:
                return 0
            s = str(N)
            n = len(s)

            @lru_cache(maxsize=None)
